// Function node: produce a clean JSON payload at $json
const incomingComments = $json.comments || []; // ensure it's an array

const comments = incomingComments
  // ADD THIS FILTER: Exclude files that are typically binary/non-text diffs
  .filter(c => {
    if (!c || !c.path || !c.body) return false;
    const path = c.path.toLowerCase();
    return !(
      path.endsWith('.png') ||
      path.endsWith('.jpg') ||
      path.endsWith('.jpeg') ||
      path.endsWith('.gif') ||
      path.endsWith('.ico') ||
      path.endsWith('.bin')
      // Add any other binary extensions you encounter
    );
  })
  .map(c => {
    // Try to get line from c.line or c.position, defaulting to 1 (first changed line)
    // We use Math.floor to ensure an integer, and check if it's > 0 (as line 0 is often invalid)
    const lineNum = Number.isFinite(Number(c.line)) ? Number(c.line) : Number(c.position);

    let finalLine = 1;
    if (Number.isFinite(lineNum) && lineNum > 0) {
      finalLine = Math.floor(lineNum);
    }

    return {
      path: String(c.path),
      // IMPORTANT: Use 'line' and 'side' instead of 'position' for reliability
      line: finalLine, 
      side: 'RIGHT', // Anchors the comment to the head branch file
      body: String(c.body).slice(0, 1000) // truncate for safety
    };
  });

return [{ json: {
  body: "Automated code review: see inline comments for details.",
  event: "COMMENT",
  comments
}}];

// Function node: parse code-fence JSON from LLM outputs and return normalized comments + PR number

function extractJsonFromCodeFence(text) {
  if (typeof text !== 'string') return null;
  const m = text.match(/```(?:json)?\n([\s\S]*?)```/);
  const candidate = m ? m[1].trim() : text.trim();
  try {
    return JSON.parse(candidate);
  } catch (e) {
    return null;
  }
}

const all = $input.all();
const comments = [];

// Helper function to normalize and push a single comment
const normalizeAndPushComment = (c, reviewBody) => {
  // Check if the line number is valid and not 0 (0 is often invalid for comments)
  const lineNumber = (typeof c.position === 'number' && Number.isFinite(c.position) && c.position > 0)
    ? c.position
    : ((typeof c.line === 'number' && Number.isFinite(c.line) && c.line > 0) ? c.line : null);
  
  // Skip if path or body is missing, or if line is invalid
  if (!c.path && !c.file) return;
  if (!c.body && !c.comment && !reviewBody) return; // Must have a body/comment

  comments.push({
    path: c.path ?? c.file ?? null,
    body: (c.body ?? c.comment ?? reviewBody ?? '').toString(),
    // IMPORTANT FIX: Use 'line' instead of 'position' and set 'side'
    line: lineNumber,
    side: 'RIGHT', // Anchor comment to the head branch file
    severity: c.severity ?? 'low'
  });
};


// iterate each input item and try to extract JSON inside content.parts[*].text
for (const item of all) {
  const json = item.json;
  let reviewBody = null; // Used for a potential top-level review body if it exists

  // 1) If the shape already contains comments at top-level, accept them
  if (Array.isArray(json.comments) && json.comments.length > 0) {
    for (const c of json.comments) {
      normalizeAndPushComment(c, json.body);
    }
    continue;
  }

  // 2) If there is content.parts[*].text (LLM shape), parse the code-fence JSON inside each part
  const parts = json?.content?.parts;
  if (Array.isArray(parts)) {
    for (const p of parts) {
      const txt = p?.text;
      if (!txt) continue;
      const parsed = extractJsonFromCodeFence(txt);
      if (!parsed) continue;

      reviewBody = parsed.body ?? null;

      // parsed might include reviewBody, comments array, or a single comment object
      if (Array.isArray(parsed.comments)) {
        for (const c of parsed.comments) {
          normalizeAndPushComment(c, reviewBody);
        }
      } else if (parsed.path || parsed.file) {
        // single comment object (must have path/file to be a comment)
        normalizeAndPushComment(parsed, reviewBody);
      }
    }
    continue;
  }

  // 3) Last fallback: maybe the item.json itself is a JSON string containing the review object
  if (typeof json === 'string') {
    const parsed = extractJsonFromCodeFence(json) || (function(){ try { return JSON.parse(json); } catch(e){ return null; } })();
    if (parsed && Array.isArray(parsed.comments)) {
      for (const c of parsed.comments) {
        normalizeAndPushComment(c, parsed.body);
      }
    }
  }
}

// Deduplicate exact duplicate comments (optional)
const seen = new Set();
const deduped = [];
for (const c of comments) {
  // Use 'line' instead of 'position' for the key
  const key = `${c.path||''}||${c.line||''}||${c.body}`;
  if (!seen.has(key)) {
    seen.add(key);
    deduped.push(c);
  }
}

// get PR number from GitHub Trigger node (adjust node name if different)
let prNumber = null;
try {
  prNumber = $('Github Trigger1').first().json?.body?.number ?? $('GitHub Trigger').first().json?.body?.number ?? null;
} catch (e) {
  // ignore
}

return [{
  json: {
    comments: deduped,
    number: prNumber
  }
}];

const instructions = `
Use meaningful and descriptive names that clearly explain the purpose.
Keep every function small, focused, and limited to a single responsibility.
Follow a consistent formatting style to improve code readability everywhere.
Write clear code so that comments are rarely ever truly necessary.
Avoid repeating logic; extract common functionality into reusable components.
Separate concerns by organizing code based on responsibility and functionality.
Write automated tests to ensure code works correctly and remains stable.
Handle errors gracefully with informative messages and proper fallback logic.
Structure your application into independent, modular, and well-defined components.
Regularly refactor and improve code to keep it clean and maintainable.
`;

for (const item of $input.all()) {
  const file = item.json;

  const reviewPrompt = `
You are a senior software engineer reviewing a pull request.

${instructions}

Review the GitHub diff for: ${file.filename}

Patch:
\`\`\`diff
${file.patch}
\`\`\`

OUTPUT FORMAT: Strict JSON (no markdown fences)
{
  "reviewBody": "One short paragraph summarizing the review for this file.",
  "comments": [
    {
      "path": "${file.filename}",
      "body": "Specific, actionable feedback tied to a single issue.",
      "position": 0
    }
  ]
}
Rules:
- Return valid JSON only (no extra text).
- "position" is the integer diff position for this file.
- Include 1–3 high-value comments; omit if nothing to add.
`;

  item.json.reviewPrompt = reviewPrompt;
}

return $input.all();
